// Verdict enumerates the outcome for a single audited claim.
type Verdict string

const (

VerdictSupported   Verdict = "supported"

VerdictMissing     Verdict = "missing"

VerdictOutOfScope  Verdict = "out_of_scope"

VerdictUnverifiable Verdict = "unverifiable"
)

// IntentPacket captures what the checkpoint claims it set out to do.
type IntentPacket struct {

CheckpointID       string   `json:"checkpoint_id"`

Prompts            []string `json:"prompts"`

TranscriptStart    int      `json:"checkpoint_transcript_start"`

DeclaredFilesTouched []string `json:"declared_files_touched"`

Model              string   `json:"model"`

Agent              string   `json:"agent"`

SkillEvents        []string `json:"skill_events,omitempty"`
}

// ImplementationEvidence captures what actually happened in git/tests/graph.
type ImplementationEvidence struct {

LinkedCommits    []string          `json:"linked_commits"`

ActualFilesTouched []string        `json:"actual_files_touched"`

Diffs            map[string]string `json:"diffs,omitempty"`

FocusedTests     []string          `json:"focused_tests,omitempty"`

GraphEvidence    json.RawMessage   `json:"graph_evidence,omitempty"`
}

// AuditFinding is one line-item comparison between intent and implementation.
type AuditFinding struct {

Claim   string  `json:"claim"`

Verdict Verdict `json:"verdict"`

Detail  string  `json:"detail"`
}

// AuditReport is the full --json output shape.
type AuditReport struct {

Intent         IntentPacket            `json:"intent"`

Implementation ImplementationEvidence  `json:"implementation"`

Findings       []AuditFinding          `json:"findings"`
}

func newCheckpointAuditCmd() *cobra.Command {

var jsonOut bool

var sessionIndex int

var testFilter string


cmd := &cobra.Command{


Use:   "audit <checkpoint-id|commit-sha>",


Short: "Audit a checkpoint's stated intent against its actual implementation",


Args:  cobra.ExactArgs(1),


RunE: func(cmd *cobra.Command, args []string) error {



return runCheckpointAudit(cmd, args[0], jsonOut, sessionIndex, testFilter)


},

}


cmd.Flags().BoolVar(&jsonOut, "json", false, "emit machine-readable JSON report")

cmd.Flags().IntVar(&sessionIndex, "session-index", -1, "audit a specific session within the checkpoint")

cmd.Flags().StringVar(&testFilter, "test", "", "restrict focused test evidence to this pattern")


return cmd
}

func runCheckpointAudit(cmd *cobra.Command, target string, jsonOut bool, sessionIndex int, testFilter string) error {

// 1. Resolve ID/commit — reuse explain's resolver, don't reinvent it.

checkpointID, err := resolveExplainCheckpointID(target)

if err != nil {


return fmt.Errorf("resolving checkpoint: %w", err)

}


// 2. Open via the existing backend-agnostic entrypoint.

store, err := newExplainCheckpointLookup(checkpointID)

if err != nil {


return fmt.Errorf("opening checkpoint store: %w", err)

}


summary, err := checkpoint.ReadCheckpoint(store, checkpointID)

if err != nil {


return fmt.Errorf("reading checkpoint summary: %w", err)

}


sessions, err := resolveAuditSessions(store, summary, sessionIndex)

if err != nil {


return err

}


// 3. Build the intent packet from prompts + declared scope.

intent := buildIntentPacket(summary, sessions)


// 4. Resolve implementation evidence from git.

commits := trailers.ParseAllCheckpoints(getCommitMessages(summary)) // handles squash commits

impl, err := gatherImplementationEvidence(commits, intent.DeclaredFilesTouched, testFilter)

if err != nil {


return fmt.Errorf("gathering implementation evidence: %w", err)

}


// 5. Optional: shell out to `entire graph` if available; degrade gracefully.

if graphOut, err := runEntireGraph(intent.DeclaredFilesTouched); err == nil {


impl.GraphEvidence = graphOut

}


// 6. Compare intent vs implementation → findings.

findings := compareIntentToImplementation(intent, impl)


report := AuditReport{Intent: intent, Implementation: impl, Findings: findings}


if jsonOut {


enc := json.NewEncoder(cmd.OutOrStdout())


enc.SetIndent("", "  ")


return enc.Encode(report)

}


renderAuditReportProse(cmd.OutOrStdout(), report)

return nil
}

